import pytest
from ferry.schedule import next_sailing, SAILINGS, as_list
from ferry.board import render


class TestNextSailing:
    def test_next_sailing_after_last_existing(self):
        """When there is nothing later in the day, return None instead of wrapping."""
        # Before the fix, this would return "06:00" (wrapping)
        # After the fix, it should return None
        assert next_sailing("10:30") is None

    def test_next_sailing_before_first(self):
        """When before the first sailing, return the first sailing."""
        assert next_sailing("05:00") == "06:00"

    def test_next_sailing_between_sailings(self):
        """When between two sailings, return the next one."""
        assert next_sailing("06:30") == "07:30"
        assert next_sailing("07:30") == "09:00"
        assert next_sailing("09:00") == "10:30"

    def test_next_sailing_exactly_on_sailing(self):
        """When exactly on a sailing time, return the next one."""
        assert next_sailing("06:00") == "07:30"
        assert next_sailing("07:30") == "09:00"
        assert next_sailing("09:00") == "10:30"

    def test_next_sailing_after_12_00(self):
        """When after 12:00, return None."""
        assert next_sailing("12:00") is None
        assert next_sailing("23:59") is None

    def test_next_sailing_12_00_exists(self):
        """12:00 should be a valid sailing."""
        assert next_sailing("10:30") == "12:00"


class TestSAILINGS:
    def test_sailings_includes_12_00(self):
        """SAILINGS should include 12:00."""
        assert "12:00" in SAILINGS

    def test_sailings_order(self):
        """SAILINGS should be in chronological order."""
        assert SAILINGS == ["06:00", "07:30", "09:00", "10:30", "12:00"]

    def test_sailings_count(self):
        """SAILINGS should have 5 entries."""
        assert len(SAILINGS) == 5


class TestAsList:
    def test_as_list_returns_list(self):
        """as_list should return a list."""
        result = as_list()
        assert isinstance(result, list)

    def test_as_list_content(self):
        """as_list should return the same content as SAILINGS."""
        assert as_list() == SAILINGS

    def test_as_list_is_plain_list_of_strings(self):
        """as_list should return a plain list of time strings."""
        result = as_list()
        for item in result:
            assert isinstance(item, str)

    def test_as_list_does_not_modify_sailings(self):
        """as_list should not modify the original SAILINGS."""
        original = list(SAILINGS)
        as_list()
        assert SAILINGS == original


class TestRender:
    def test_render_format(self):
        """render should return pipe-separated time strings."""
        result = render()
        assert "|" in result

    def test_render_content(self):
        """render should contain all sailing times."""
        result = render()
        for sailing in SAILINGS:
            assert sailing in result

    def test_render_order(self):
        """render should list sailings in order."""
        result = render()
        # Check that 06:00 comes before 07:30, etc.
        parts = result.split(" | ")
        for i in range(len(parts) - 1):
            assert parts[i] < parts[i + 1]
